import glob, json, re

# A simple yaml parser / key extractor since PyYAML might not be installed, or we can check python's json / simple parsing
def parse_yaml_simple(text):
    data = {}
    stack = [data]
    indents = [-1]
    for line in text.splitlines():
        if not line.strip() or line.strip().startswith('#'):
            continue
        indent = len(line) - len(line.lstrip())
        content = line.strip()
        if ':' in content:
            parts = content.split(':', 1)
            key = parts[0].strip()
            val_part = parts[1].strip().split('#')[0].strip()

            while indent <= indents[-1]:
                stack.pop()
                indents.pop()

            if not val_part:
                # new dict
                new_dict = {}
                stack[-1][key] = new_dict
                stack.append(new_dict)
                indents.append(indent)
            else:
                # parse value
                if val_part.lower() == 'true':
                    val = True
                elif val_part.lower() == 'false':
                    val = False
                elif val_part.isdigit():
                    val = int(val_part)
                else:
                    # remove quotes if any
                    val = val_part.strip('\"\'')
                stack[-1][key] = val
    return data

uniform_keys = [
    'service.port', 'service.request_timeout_ms', 'service.max_body_kb',
    'database.pool_size', 'database.statement_timeout_ms', 'database.ssl_mode',
    'cache.ttl_s', 'cache.max_entries', 'auth.issuer', 'auth.token_ttl_s',
    'auth.allow_anonymous', 'tls.verify', 'tls.min_version', 'logging.format',
    'logging.sample_rate', 'features.new_checkout', 'features.async_refunds',
    'features.rate_limiting', 'payments.provider', 'payments.retry_limit',
    'payments.backoff_ms', 'payments.idempotency', 'database.port',
    'auth.required_scopes', 'service.name'
]

files = glob.glob('config/*.yaml')
configs = {}
for f in files:
    with open(f) as fh:
        configs[f] = parse_yaml_simple(fh.read())

for k in uniform_keys:
    parts = k.split('.')
    values = {}
    for f, cfg in configs.items():
        val = cfg
        for p in parts:
            val = val.get(p) if isinstance(val, dict) else None
        values[f] = val

